item.stdout:
{"connection_id": "BC-d013ec99c282519ce8df", "ref": "Augustine, City of God 21.26", "target": "sec18", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Paul's fire as postmortem purification", "note": "The commentary distinguishes fire that guides or corrects from fire endured as punishment; Augustine discusses the fire that tests works in 1 Corinthians 3 as a possible temporal purification after death, a Christian interpretation that makes the fire's function contested."}
{"connection_id": "BC-94f231981e34557fef57", "ref": "Didache 1.1", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "two ways, life and death", "note": "The commentary divides hearers between a destructive fate and purification with prayer; the Didache opens by distinguishing a way of life from a way of death, giving an early Christian ethical frame for the divided response."}
{"connection_id": "BC-6cbb2fc10593675f202d", "ref": "Gregory of Nyssa, Life of Moses II.20–21", "target": "sec18", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "The unconsumed bush in Christian typology", "note": "In the burning-bush interpretation commonly placed in these sections, Gregory reads the bush's non-consumption through later Christian typology; the section numbering should be checked, but it is a concrete reception of the fire detail central to the commentary."}
{"connection_id": "BC-cdfde60e0201668b2e06", "ref": "Martyrdom of Polycarp 11.2", "target": "sec18", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "A governor's brief fire and future judgment", "note": "Polycarp answers a ruler's fire threat by contrasting a short-lived flame with future judgment; the martyr tradition sharpens the commentary's contrast between Pharaoh's claimed lasting punishment and divine permanence."}
{"connection_id": "BC-f6eb9706144cf9d99820", "ref": "SBLGNT:1Cor.15.42", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "perishable sown, imperishable raised", "note": "The commentary links the body's formation to pasture and contrasts the transient with the lasting; Paul uses sowing to describe a perishable body raised imperishable, making the agricultural image explicitly bodily and eschatological."}
{"connection_id": "BC-0d5cdf6415d27df7a61f", "ref": "SBLGNT:1Cor.15.44", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "natural and spiritual body", "note": "The commentary joins embodied formation to the hereafter's lasting life; Paul distinguishes the natural body from the spiritual body in the resurrection, extending that body-and-future connection."}
{"connection_id": "BC-1caed5288f5dbffc1934", "ref": "SBLGNT:1Cor.3.13", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "works tested by fire", "note": "The commentary joins fire with the difference between what is lost and what remains useful; Paul says fire tests each person's work, making fire a test of lasting value."}
{"connection_id": "BC-cfebdc4ce029e8859829", "ref": "SBLGNT:1Cor.3.13", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "Fire tests the quality of each work", "note": "Paul's fire reveals whether work endures, directly extending the commentary's fire, useful remainder, and lasting good into a Christian assessment of works."}
{"connection_id": "BC-7f0682977afeb21cb120", "ref": "SBLGNT:1Cor.3.14", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "work remains and receives reward", "note": "The commentary says useful yield remains and receives its due; Paul says the work that survives the fire receives a reward, an explicit ethical form of that contrast."}
{"connection_id": "BC-d94ff1d71ae0eb2ca080", "ref": "SBLGNT:1Cor.3.15", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "work burned, person saved", "note": "The commentary contrasts the one who enters fire with the one who performs lasting good; Paul distinguishes burned work from the person saved through fire, complicating the image without equating the passages."}
{"connection_id": "BC-2f7d72f9e99325642787", "ref": "SBLGNT:1Cor.3.15", "target": "sec18", "tradition": "incil", "kind": "karsi_anlati", "basis": "Saved as through fire", "note": "Paul can describe a person whose work burns yet who is saved through fire; that different result makes a useful counterpoint to the commentary's condemned person inside the great fire."}
{"connection_id": "BC-edc6145a4048a5f31c2e", "ref": "SBLGNT:1Cor.4.5", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "Hidden things brought to light at judgment", "note": "God will disclose hidden things of darkness and heart-motives, giving a judgmental sequel to the commentary's hidden matter and differentiated outcomes."}
{"connection_id": "BC-2e7796911c1b5123fde9", "ref": "SBLGNT:1John.2.17", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "world passes, God's will remains", "note": "The commentary says people prefer worldly life though the hereafter is more lasting; John explicitly contrasts the passing world and its desire with the one who does God's will abiding forever."}
{"connection_id": "BC-501bb0911ac5d9744f85", "ref": "SBLGNT:1John.2.17", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "The world passes, the doer remains", "note": "The world and its desire pass away while the one doing God's will remains forever, directly matching the commentary's transient life and lasting good."}
{"connection_id": "BC-9d14e81fc1a00981d453", "ref": "SBLGNT:1John.3.3", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "Hope issuing in self-purification", "note": "Those who hold the eschatological hope purify themselves, a compact Christian parallel to the commentary's purified person oriented toward the enduring future."}
{"connection_id": "BC-a7213361e1f650d4f621", "ref": "SBLGNT:1Pet.1.23", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "imperishable seed and living word", "note": "The commentary joins remembered revelation to the field's lasting yield; Peter says new birth comes through imperishable seed, the living and abiding word, connecting word and agriculture."}
{"connection_id": "BC-019a12a0da758b4fadb8", "ref": "SBLGNT:1Pet.1.24", "target": "sec18", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Isaiah's grass applied to human mortality", "note": "The commentary identifies worldly life with withering pasture; Peter reapplies Isaiah's grass-and-flower image to mortal flesh, showing the Christian reception of that transience text."}
{"connection_id": "BC-ef0ec9b0b8080ea3ad34", "ref": "SBLGNT:1Pet.1.24", "target": "sec18", "tradition": "incil", "kind": "paralel", "basis": "All flesh as grass", "note": "First Peter reapplies the grass-and-fading-flower image to mortal human life, a Christian articulation of the commentary's worldly-life-as-grass scene."}
{"connection_id": "BC-6699b5aabc1c1594c9ea", "ref": "SBLGNT:1Pet.1.25", "target": "sec18", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "word as enduring gospel", "note": "The commentary sets the passing world against the lasting better life; Peter's quotation of Isaiah identifies the enduring word with the gospel preached, a Christian interpretive extension of the contrast."}
{"connection_id": "BC-57d6e7645413f35cf6c8", "ref": "SBLGNT:1Pet.1.25", "target": "sec18", "tradition": "incil", "kind": "paralel", "basis": "The word remains forever", "note": "The citation's next verse makes the Lord's word endure forever, matching the commentary's passage from drying life to an enduring word and future."}
{"connection_id": "BC-5fd5fe04c1fa64412601", "ref": "SBLGNT:1Pet.1.7", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "Faith tested as gold by fire", "note": "The letter compares tested faith to gold proved by fire, a Christian refinement image for the commentary's corrective fire and enduring value."}
{"connection_id": "BC-6644b23461c03ed5cded", "ref": "SBLGNT:2Cor.4.18", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "seen temporary, unseen eternal", "note": "The commentary says worldly life is preferred though the hereafter is better and more abiding; Paul explicitly contrasts visible things that are temporary with unseen things that are eternal."}
{"connection_id": "BC-b57bf1cf6b447feb4550", "ref": "SBLGNT:2Cor.4.18", "target": "sec18", "tradition": "incil", "kind": "motif", "basis": "Seen things temporary and unseen things eternal", "note": "Paul explicitly contrasts the temporary visible with the eternal unseen, giving the commentary's dunya-versus-lasting formulation a close Christian analogue."}
